# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require "rake"

RSpec.describe "timekeeping:alerts" do
  # A refused metrics read must not look like a healthy run with nothing to report.
  it "exits non-zero and never reports no alerts when the metrics endpoint refuses the token" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!
    saved = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    token = SecureRandom.hex(24)
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .to_return(status: 401, body: JSON.generate(reason: "unauthorized"))

    stdout = StringIO.new
    stderr = StringIO.new
    original_stdout, original_stderr = $stdout, $stderr
    $stdout, $stderr = stdout, stderr
    begin
      expect { Rake::Task["timekeeping:alerts"].invoke }.to raise_error(SystemExit) { |exit|
        expect(exit.status).not_to eq(0)
      }
    ensure
      $stdout, $stderr = original_stdout, original_stderr
    end

    expect(stdout.string).not_to match(/no alerts/i)
    expect(stdout.string + stderr.string).not_to include(token)
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = saved[key] }
  end
end
